settings.liquid:
{%- comment -%}
  Carrossel de Depoimentos em Video (Home) - Custom Liquid
  America Nutrition - v2.0

  COMO USAR: cole este codigo inteiro num bloco "Custom Liquid"
  no editor de tema.

  Busca os depoimentos via Storefront API (mesma fonte da galeria),
  filtrando apenas videos. Pega TODOS os videos, nao so os 50 do Liquid.
  Cards verticais 9:16 com lightbox.

  AJUSTES: veja MAX_VIDEOS no inicio do script, e as variaveis de cor
  no style do primeiro div.
{%- endcomment -%}

<div class="dep-carrossel-section" id="dep-car-home"
     style="
       --dc-cor-primaria: #08398E;
       --dc-cor-borda: #08398E;
       --dc-bg: #FFFFFF;
       --dc-pad-top: 20px;
       --dc-pad-bottom: 20px;
     ">

  <div class="dep-car-viewport">
    <button class="dep-car-seta dep-car-seta-prev" aria-label="Anterior" type="button">
      <svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2.5">
        <polyline points="15 18 9 12 15 6"/>
      </svg>
    </button>

    <div class="dep-car-track" id="dep-track-home">
      <div class="dep-car-card dep-car-skeleton"><div class="dep-car-midia"></div></div>
      <div class="dep-car-card dep-car-skeleton"><div class="dep-car-midia"></div></div>
      <div class="dep-car-card dep-car-skeleton"><div class="dep-car-midia"></div></div>
      <div class="dep-car-card dep-car-skeleton"><div class="dep-car-midia"></div></div>
      <div class="dep-car-card dep-car-skeleton"><div class="dep-car-midia"></div></div>
    </div>

    <button class="dep-car-seta dep-car-seta-next" aria-label="Proximo" type="button">
      <svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2.5">
        <polyline points="9 18 15 12 9 6"/>
      </svg>
    </button>
  </div>

  <div class="dep-car-dots" id="dep-dots-home"></div>
</div>

<div class="dep-car-lightbox" id="dep-lb-home" aria-hidden="true">
  <button class="dep-lb-fechar" aria-label="Fechar" type="button">&times;</button>
  <button class="dep-lb-prev" aria-label="Anterior" type="button">&#10094;</button>
  <button class="dep-lb-next" aria-label="Proximo" type="button">&#10095;</button>
  <div class="dep-lb-content"></div>
</div>

<style>
  #dep-car-home {
    background: var(--dc-bg);
    padding-top: var(--dc-pad-top);
    padding-bottom: var(--dc-pad-bottom);
    overflow: hidden;
  }

  #dep-car-home .dep-car-viewport {
    position: relative;
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 24px;
  }

  #dep-car-home .dep-car-track {
    display: flex;
    gap: 18px;
    overflow-x: auto;
    scroll-behavior: smooth;
    scroll-snap-type: x mandatory;
    -webkit-overflow-scrolling: touch;
    padding: 8px 4px 16px;
    scrollbar-width: none;
  }

  #dep-car-home .dep-car-track::-webkit-scrollbar { display: none; }

  #dep-car-home .dep-car-card {
    flex: 0 0 auto;
    width: 200px;
    scroll-snap-align: start;
  }

  #dep-car-home .dep-car-midia {
    position: relative;
    width: 100%;
    aspect-ratio: 9 / 16;
    border-radius: 20px;
    overflow: hidden;
    cursor: pointer;
    background: #e8eef7;
    border: 4px solid var(--dc-cor-borda);
    box-shadow: 0 8px 24px rgba(8, 57, 142, 0.18);
    transition: transform 0.25s ease, box-shadow 0.25s ease;
  }

  #dep-car-home .dep-car-midia:hover {
    transform: translateY(-6px);
    box-shadow: 0 14px 32px rgba(8, 57, 142, 0.28);
  }

  #dep-car-home .dep-car-poster {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
  }

  #dep-car-home .dep-car-play {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    pointer-events: none;
  }

  #dep-car-home .dep-car-play::before {
    content: "";
    position: absolute;
    width: 64px;
    height: 64px;
    background: rgba(255, 255, 255, 0.28);
    border: 2px solid rgba(255, 255, 255, 0.85);
    border-radius: 50%;
    backdrop-filter: blur(2px);
  }

  #dep-car-home .dep-car-play svg {
    position: relative;
    margin-left: 4px;
    filter: drop-shadow(0 2px 6px rgba(0,0,0,0.4));
  }

  #dep-car-home .dep-car-skeleton .dep-car-midia {
    border-color: #d4deef;
    background: linear-gradient(90deg, #e8eef7 25%, #f2f5fa 50%, #e8eef7 75%);
    background-size: 200% 100%;
    animation: dep-shimmer 1.4s infinite;
    cursor: default;
  }

  #dep-car-home .dep-car-skeleton .dep-car-midia:hover {
    transform: none;
    box-shadow: 0 8px 24px rgba(8, 57, 142, 0.18);
  }

  @keyframes dep-shimmer {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
  }

  #dep-car-home .dep-car-seta {
    position: absolute;
    top: calc(50% - 8px);
    transform: translateY(-50%);
    z-index: 3;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    border: none;
    background: #fff;
    color: var(--dc-cor-primaria);
    box-shadow: 0 4px 14px rgba(0,0,0,0.18);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.2s, transform 0.15s;
  }

  #dep-car-home .dep-car-seta:hover {
    background: var(--dc-cor-primaria);
    color: #fff;
  }

  #dep-car-home .dep-car-seta:active {
    transform: translateY(-50%) scale(0.92);
  }

  #dep-car-home .dep-car-seta-prev { left: 4px; }
  #dep-car-home .dep-car-seta-next { right: 4px; }

  #dep-car-home .dep-car-seta[disabled] {
    opacity: 0.35;
    cursor: default;
    pointer-events: none;
  }

  #dep-car-home .dep-car-dots {
    display: flex;
    justify-content: center;
    flex-wrap: wrap;
    gap: 7px;
    margin-top: 18px;
  }

  #dep-car-home .dep-car-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    border: none;
    background: #c7d2e3;
    cursor: pointer;
    padding: 0;
    transition: background 0.2s, width 0.2s;
  }

  #dep-car-home .dep-car-dot.ativo {
    background: var(--dc-cor-primaria);
    width: 22px;
    border-radius: 4px;
  }

  #dep-car-home .dep-car-vazio {
    text-align: center;
    color: #888;
    padding: 2rem;
    width: 100%;
  }

  @media (max-width: 700px) {
    #dep-car-home .dep-car-card { width: 210px; }
    #dep-car-home .dep-car-seta { display: none; }
  }

  #dep-lb-home {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.93);
    z-index: 99999;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 20px;
  }

  #dep-lb-home.ativo { display: flex; }

  #dep-lb-home .dep-lb-content {
    display: flex;
    align-items: center;
    justify-content: center;
  }

  #dep-lb-home .dep-lb-content video {
    max-width: 92vw;
    max-height: 88vh;
    width: auto;
    height: auto;
    border-radius: 12px;
    background: #000;
  }

  #dep-lb-home .dep-lb-fechar,
  #dep-lb-home .dep-lb-prev,
  #dep-lb-home .dep-lb-next {
    position: absolute;
    background: rgba(255,255,255,0.12);
    border: none;
    color: #fff;
    font-size: 2rem;
    width: 52px;
    height: 52px;
    border-radius: 50%;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.2s;
  }

  #dep-lb-home .dep-lb-fechar:hover,
  #dep-lb-home .dep-lb-prev:hover,
  #dep-lb-home .dep-lb-next:hover {
    background: rgba(255,255,255,0.25);
  }

  #dep-lb-home .dep-lb-fechar { top: 18px; right: 18px; }
  #dep-lb-home .dep-lb-prev { left: 18px; top: 50%; transform: translateY(-50%); }
  #dep-lb-home .dep-lb-next { right: 18px; top: 50%; transform: translateY(-50%); }

  @media (max-width: 600px) {
    #dep-lb-home .dep-lb-prev,
    #dep-lb-home .dep-lb-next {
      width: 40px; height: 40px; font-size: 1.4rem;
    }
  }
</style>

<script>
  (function() {
    var SHOPIFY_DOMAIN = 'imunofosfo.myshopify.com';
    var STOREFRONT_TOKEN = '5d67469f488ffea95b24072a0b5ac98c';
    var STOREFRONT_VERSION = '2024-10';
    var MAX_VIDEOS = 15;

    var section = document.getElementById('dep-car-home');
    if (!section) return;

    var track = document.getElementById('dep-track-home');
    var dotsWrap = document.getElementById('dep-dots-home');
    var lightbox = document.getElementById('dep-lb-home');
    var content = lightbox.querySelector('.dep-lb-content');
    var btnFechar = lightbox.querySelector('.dep-lb-fechar');
    var btnPrev = lightbox.querySelector('.dep-lb-prev');
    var btnNext = lightbox.querySelector('.dep-lb-next');
    var setaPrev = section.querySelector('.dep-car-seta-prev');
    var setaNext = section.querySelector('.dep-car-seta-next');

    var videos = [];
    var cards = [];
    var dots = [];
    var indexAtual = 0;

    function fetchPagina(after) {
      var query = [
        'query GetDeps($first: Int!, $after: String) {',
        '  metaobjects(type: "depoimento", first: $first, after: $after, sortKey: "id", reverse: true) {',
        '    edges {',
        '      cursor',
        '      node {',
        '        id',
        '        tipo: field(key: "tipo") { value }',
        '        midia: field(key: "midia") {',
        '          reference {',
        '            ... on Video {',
        '              sources { url mimeType }',
        '              previewImage { url }',
        '            }',
        '          }',
        '        }',
        '        produto: field(key: "produto") {',
        '          reference { ... on Product { title handle } }',
        '        }',
        '      }',
        '    }',
        '    pageInfo { hasNextPage endCursor }',
        '  }',
        '}'
      ].join('\n');

      return fetch('https://' + SHOPIFY_DOMAIN + '/api/' + STOREFRONT_VERSION + '/graphql.json', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Shopify-Storefront-Access-Token': STOREFRONT_TOKEN
        },
        body: JSON.stringify({ query: query, variables: { first: 50, after: after } })
      }).then(function(r) { return r.json(); });
    }

    function escolherFonteVideo(sources) {
      if (!sources || !sources.length) return null;
      for (var i = 0; i < sources.length; i++) {
        if (sources[i].mimeType === 'video/mp4') return sources[i].url;
      }
      return sources[0].url;
    }

    async function carregarVideos() {
      var after = null;
      var hasNext = true;
      var tentativas = 0;

      try {
        while (hasNext && videos.length < MAX_VIDEOS && tentativas < 8) {
          tentativas++;
          var data = await fetchPagina(after);
          if (data.errors) {
            console.error('Storefront API erro:', data.errors);
            break;
          }
          var mo = data.data.metaobjects;
          mo.edges.forEach(function(edge) {
            if (videos.length >= MAX_VIDEOS) return;
            var node = edge.node;
            var tipo = node.tipo && node.tipo.value;
            if (tipo !== 'video') return;
            var ref = node.midia && node.midia.reference;
            if (!ref) return;
            var src = escolherFonteVideo(ref.sources);
            if (!src) return;
            videos.push({
              videoSrc: src,
              poster: ref.previewImage ? ref.previewImage.url : '',
              produto: node.produto && node.produto.reference ? node.produto.reference.title : ''
            });
          });
          hasNext = mo.pageInfo.hasNextPage;
          after = mo.pageInfo.endCursor;
        }
      } catch (e) {
        console.error('Erro ao carregar depoimentos:', e);
      }

      renderizar();
    }

    function renderizar() {
      track.innerHTML = '';

      if (videos.length === 0) {
        track.innerHTML = '<p class="dep-car-vazio">Nenhum depoimento em video disponivel.</p>';
        return;
      }

      videos.forEach(function(v, i) {
        var card = document.createElement('div');
        card.className = 'dep-car-card';
        card.dataset.index = i;

        var midia = document.createElement('div');
        midia.className = 'dep-car-midia';

        if (v.poster) {
          var img = document.createElement('img');
          img.className = 'dep-car-poster';
          img.src = v.poster;
          img.loading = 'lazy';
          img.alt = 'Depoimento ' + (v.produto || '');
          midia.appendChild(img);
        } else {
          var vid = document.createElement('video');
          vid.className = 'dep-car-poster';
          vid.muted = true;
          vid.playsInline = true;
          vid.preload = 'metadata';
          vid.src = v.videoSrc + '#t=0.5';
          midia.appendChild(vid);
        }

        var play = document.createElement('div');
        play.className = 'dep-car-play';
        play.innerHTML = '<svg viewBox="0 0 24 24" fill="#fff" width="32" height="32"><path d="M8 5v14l11-7z"/></svg>';
        midia.appendChild(play);

        midia.addEventListener('click', function() { abrir(i); });
        card.appendChild(midia);
        track.appendChild(card);
      });

      cards = Array.prototype.slice.call(track.querySelectorAll('.dep-car-card'));
      montarDots();
      atualizaSetas();
      atualizaDots();
    }

    function passoScroll() {
      var card = cards[0];
      if (!card) return 300;
      var estilo = window.getComputedStyle(track);
      var gap = parseFloat(estilo.columnGap || estilo.gap || 18);
      return card.offsetWidth + gap;
    }

    function atualizaSetas() {
      if (!setaPrev || !setaNext) return;
      var maxScroll = track.scrollWidth - track.clientWidth - 2;
      setaPrev.disabled = track.scrollLeft <= 2;
      setaNext.disabled = track.scrollLeft >= maxScroll;
    }

    function montarDots() {
      dotsWrap.innerHTML = '';
      cards.forEach(function(card, i) {
        var dot = document.createElement('button');
        dot.className = 'dep-car-dot';
        dot.type = 'button';
        dot.setAttribute('aria-label', 'Ir para depoimento ' + (i + 1));
        dot.addEventListener('click', function() {
          track.scrollTo({ left: passoScroll() * i, behavior: 'smooth' });
        });
        dotsWrap.appendChild(dot);
      });
      dots = Array.prototype.slice.call(dotsWrap.querySelectorAll('.dep-car-dot'));
    }

    function atualizaDots() {
      var passo = passoScroll();
      var ativo = Math.round(track.scrollLeft / passo);
      dots.forEach(function(d, i) {
        d.classList.toggle('ativo', i === ativo);
      });
    }

    if (setaPrev) setaPrev.addEventListener('click', function() {
      track.scrollBy({ left: -passoScroll(), behavior: 'smooth' });
    });
    if (setaNext) setaNext.addEventListener('click', function() {
      track.scrollBy({ left: passoScroll(), behavior: 'smooth' });
    });

    var scrollTimer;
    track.addEventListener('scroll', function() {
      window.clearTimeout(scrollTimer);
      scrollTimer = window.setTimeout(function() {
        atualizaSetas();
        atualizaDots();
      }, 60);
    });

    window.addEventListener('resize', function() {
      atualizaSetas();
      atualizaDots();
    });

    function abrir(index) {
      indexAtual = index;
      var v = videos[index];
      content.innerHTML = '';

      var video = document.createElement('video');
      video.src = v.videoSrc;
      video.controls = true;
      video.autoplay = true;
      video.playsInline = true;
      content.appendChild(video);

      lightbox.classList.add('ativo');
      lightbox.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
    }

    function fechar() {
      var v = content.querySelector('video');
      if (v) { v.pause(); }
      lightbox.classList.remove('ativo');
      lightbox.setAttribute('aria-hidden', 'true');
      content.innerHTML = '';
      document.body.style.overflow = '';
    }

    function navegar(dir) {
      var novo = (indexAtual + dir + videos.length) % videos.length;
      abrir(novo);
    }

    btnFechar.addEventListener('click', fechar);
    btnPrev.addEventListener('click', function() { navegar(-1); });
    btnNext.addEventListener('click', function() { navegar(1); });

    lightbox.addEventListener('click', function(e) {
      if (e.target === lightbox) fechar();
    });

    document.addEventListener('keydown', function(e) {
      if (!lightbox.classList.contains('ativo')) return;
      if (e.key === 'Escape') fechar();
      if (e.key === 'ArrowLeft') navegar(-1);
      if (e.key === 'ArrowRight') navegar(1);
    });

    carregarVideos();
  })();
</script>
